mapper.select:
SELECT *, CAST(source_versions_json AS BINARY) AS utf8_source_versions_json
FROM ai_agent_action
WHERE workspace_id = #{workspaceId} AND root_run_id = #{rootRunId} AND id = #{id}

SELECT *, CAST(source_versions_json AS BINARY) AS utf8_source_versions_json
FROM ai_agent_action
WHERE workspace_id = #{workspaceId} AND root_run_id = #{rootRunId} AND action_slot = #{actionSlot}

SELECT *, CAST(source_versions_json AS BINARY) AS utf8_source_versions_json
FROM ai_agent_action
WHERE workspace_id = #{workspaceId} AND root_run_id = #{rootRunId} AND semantic_slot_key = #{semanticSlotKey}

mapper.update:
UPDATE ai_agent_action SET
  preparation_id = #{action.preparationId}, intent_fingerprint = #{action.intentFingerprint},
  prepared_at = #{action.preparedAt}, source_observed_at = #{action.sourceObservedAt},
  source_versions_json = CONVERT(#{action.sourceVersionsJson,jdbcType=VARBINARY,typeHandler=ooo.klae.connex.backend.mappers.AiIdentifierUtf8TextTypeHandler} USING utf8mb4),
  origin_segment_id = #{action.originSegmentId},
  origin_execution_generation = #{action.originExecutionGeneration}
WHERE workspace_id = #{action.workspaceId} AND root_run_id = #{action.rootRunId}
  AND id = #{action.id} AND preparation_id IS NULL AND output_ordinal IS NULL
  AND privacy_generation = #{action.privacyGeneration}

UPDATE ai_agent_action SET output_ordinal = #{ordinal}
WHERE workspace_id = #{workspaceId} AND root_run_id = #{rootRunId} AND id = #{id}
  AND preparation_id IS NOT NULL AND output_ordinal IS NULL

mapper.delete:
DELETE FROM ai_agent_action
WHERE workspace_id = #{workspaceId} AND root_run_id = #{rootRunId}
  AND id IN #{id}
LIMIT 25
